"use client";

import { useRef } from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";

gsap.registerPlugin(useGSAP);

type HeroProps = {
  title?: string;
  subtitle?: string;
};

export function Hero({
  title = "Ideas que dejan huella.",
  subtitle = "Diseñamos experiencias digitales precisas, expresivas y pensadas para crecer junto a tu marca.",
}: HeroProps) {
  const heroRef = useRef<HTMLElement>(null);

  useGSAP(
    () => {
      const media = gsap.matchMedia();

      media.add("(prefers-reduced-motion: no-preference)", () => {
        gsap.from("[data-hero-reveal]", {
          autoAlpha: 0,
          y: 24,
          duration: 0.9,
          stagger: 0.14,
          ease: "power3.out",
          clearProps: "transform,opacity,visibility",
        });
      });

      media.add("(prefers-reduced-motion: reduce)", () => {
        gsap.set("[data-hero-reveal]", {
          autoAlpha: 1,
          y: 0,
        });
      });

      return () => media.revert();
    },
    { scope: heroRef },
  );

  return (
    <section
      ref={heroRef}
      className="relative isolate flex min-h-[80svh] items-center overflow-hidden bg-[#f3efe7] px-6 py-24 text-[#171714] sm:px-10 lg:px-16"
      aria-labelledby="hero-title"
    >
      <div
        aria-hidden="true"
        className="absolute -right-28 top-1/2 size-[28rem] -translate-y-1/2 rounded-full border border-[#171714]/10 sm:size-[42rem]"
      />

      <div
        aria-hidden="true"
        className="absolute right-[12%] top-[18%] size-3 rounded-full bg-[#e04b2f]"
      />

      <div className="relative mx-auto w-full max-w-6xl">
        <p
          data-hero-reveal
          className="mb-7 text-xs font-semibold uppercase tracking-[0.28em] text-[#e04b2f]"
        >
          Estudio digital independiente
        </p>

        <h1
          id="hero-title"
          data-hero-reveal
          className="max-w-5xl text-balance font-serif text-[clamp(3.5rem,9vw,8.5rem)] leading-[0.88] tracking-[-0.055em]"
        >
          {title}
        </h1>

        <p
          data-hero-reveal
          className="mt-9 max-w-xl text-pretty text-lg leading-relaxed text-[#171714]/65 sm:text-xl"
        >
          {subtitle}
        </p>
      </div>
    </section>
  );
}
```

Es un Client Component para Next.js App Router, usa `@gsap/react`, limita la animación al Hero y respeta `prefers-reduced-motion`.
